(async function () {
  try {
    const r = await fetch('/api/public/settings'); if (!r.ok) return;
    const s = await r.json(); if (!s) return;
    if (s.title) document.title = s.title;
    const meta = (n, v) => { if (!v) return; const m = document.querySelector('meta[name="' + n + '"]'); if (m) m.setAttribute('content', v); };
    meta('description', s.description); meta('keywords', s.keywords);
    // 备案号文字与链接（中英文都生效；留空 icpUrl 则不可点击）
    const icpA = document.getElementById('footer-icp');
    if (icpA) {
      if (s.icp) icpA.textContent = s.icp;
      if (s.icpUrl) icpA.setAttribute('href', s.icpUrl);
      else { icpA.removeAttribute('href'); icpA.style.cursor = 'default'; }
    }
    if (localStorage.getItem('lang') !== 'en') { // 英文版由词典翻译，避免被中文覆盖
      const set = (id, v) => { const el = document.getElementById(id); if (el && v != null && v !== '') el.textContent = v; };
      set('footer-tagline', s.footerTagline);
      set('contact-phone', s.contactPhone);
      set('contact-fax', s.contactFax);
      set('contact-address', s.contactAddress);
    }
  } catch (e) { /* 静默：设置不可用时保留页面默认值 */ }
})();

(function () {
  const btn = document.getElementById('search-btn');
  const modal = document.getElementById('search-modal');
  const input = document.getElementById('search-input');
  const results = document.getElementById('search-results');
  const closeBtn = document.getElementById('search-close');
  const hint = document.getElementById('search-hint');
  if (!btn || !modal) return;
  const TXT = {
    zh: { ph: '搜索产品、解决方案、新闻、资料…', hint: '回车搜索 · 点击结果直达 · Esc 关闭', none: '未找到相关内容', fail: '搜索失败，请稍后重试' },
    en: { ph: 'Search products, solutions, news, downloads…', hint: 'Enter to search · click a result · Esc to close', none: 'No results found', fail: 'Search failed, please retry' }
  };
  const L = () => TXT[localStorage.getItem('lang') === 'en' ? 'en' : 'zh'];
  const esc = (s) => String(s == null ? '' : s).replace(/[&<>"]/g, (m) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[m]));
  const open = () => { input.placeholder = L().ph; hint.textContent = L().hint; modal.classList.remove('hidden'); document.body.classList.add('overflow-hidden'); setTimeout(() => input.focus(), 30); };
  const close = () => { modal.classList.add('hidden'); document.body.classList.remove('overflow-hidden'); input.value = ''; results.innerHTML = ''; };
  btn.addEventListener('click', open);
  closeBtn.addEventListener('click', close);
  modal.addEventListener('click', (e) => { if (e.target === modal) close(); });
  document.addEventListener('keydown', (e) => { if (e.key === 'Escape' && !modal.classList.contains('hidden')) close(); });
  let t, lastSearchQ = '';
  const run = async () => {
    const q = input.value.trim();
    if (!q) { results.innerHTML = ''; return; }
    const lang = localStorage.getItem('lang') === 'en' ? 'en' : 'zh';
    try {
      const r = await fetch('/api/public/search?lang=' + lang + '&q=' + encodeURIComponent(q));
      const list = await r.json();
      if (q.length >= 2 && q !== lastSearchQ) { lastSearchQ = q; try { window.__track && window.__track('site_search', { q: q, results: Array.isArray(list) ? list.length : 0 }); } catch (_) {} }
      if (!Array.isArray(list) || !list.length) { results.innerHTML = '<div class="p-6 text-center text-sm text-gray-500">' + L().none + '</div>'; return; }
      results.innerHTML = list.map((it) => '<a href="' + esc(it.route) + '" data-kind="' + esc(it.kind) + '" data-id="' + esc(it.id) + '" class="search-item flex items-start gap-3 px-4 py-3 hover:bg-gray-50 border-b border-gray-100 last:border-0">'
        + '<span class="shrink-0 mt-0.5 inline-flex items-center px-2 py-0.5 rounded text-xs bg-primary-light text-primary">' + esc(it.type) + '</span>'
        + '<span class="min-w-0"><span class="block text-sm font-medium text-gray-900 truncate">' + esc(it.title) + '</span>'
        + (it.snippet ? '<span class="block text-xs text-gray-500 truncate">' + esc(it.snippet) + '</span>' : '') + '</span></a>').join('');
    } catch (e) { results.innerHTML = '<div class="p-6 text-center text-sm text-gray-500">' + L().fail + '</div>'; }
  };
  input.addEventListener('input', () => { clearTimeout(t); t = setTimeout(run, 200); });
  input.addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); run(); } });
  results.addEventListener('click', (e) => {
    const a = e.target.closest('.search-item');
    if (!a) return;
    if (a.getAttribute('data-kind') === 'news') {
      e.preventDefault();
      const id = a.getAttribute('data-id');
      close();
      if (window.openNewsById) window.openNewsById(id); else { location.hash = '#news'; }
    } else {
      close();
    }
  });
})();

(function () {
  const TRIGGERS = { 'open-privacy': 'privacy-modal', 'open-legal': 'legal-modal' };
  const openM = (el) => { el.classList.remove('hidden'); el.classList.add('flex'); document.body.style.overflow = 'hidden'; };
  const closeM = (el) => { el.classList.add('hidden'); el.classList.remove('flex'); document.body.style.overflow = ''; };
  document.addEventListener('click', (e) => {
    for (const cls in TRIGGERS) {
      if (e.target.closest('.' + cls)) { e.preventDefault(); const m = document.getElementById(TRIGGERS[cls]); if (m) openM(m); return; }
    }
    const pm = document.getElementById('privacy-modal'), lm = document.getElementById('legal-modal');
    if (pm && (e.target === pm || e.target.closest('#privacy-close'))) closeM(pm);
    if (lm && (e.target === lm || e.target.closest('#legal-close'))) closeM(lm);
  });
  document.addEventListener('keydown', (e) => {
    if (e.key !== 'Escape') return;
    ['privacy-modal', 'legal-modal'].forEach((id) => { const m = document.getElementById(id); if (m && !m.classList.contains('hidden')) closeM(m); });
  });
})();

// 业务咨询表单 → 提交到 /api/lead（与留资弹窗同后端；含隐私同意校验）
(function () {
  const cf = document.getElementById('contact-form');
  if (!cf) return;
  const msg = document.getElementById('contact-msg');
  const setMsg = (t, ok) => { if (!msg) return; msg.textContent = t; msg.className = 'text-sm ' + (ok ? 'text-green-600' : 'text-red-500'); msg.classList.remove('hidden'); };
  cf.addEventListener('submit', async (e) => {
    e.preventDefault();
    const f = cf.elements;
    const name = f.name.value.trim(), phone = f.phone.value.trim(), message = f.message.value.trim();
    if (!name || !phone) { setMsg('请填写姓名和联系电话', false); return; }
    if (!message) { setMsg('请填写咨询内容', false); return; }
    if (!f.consent || !f.consent.checked) { setMsg('请先阅读并勾选同意《隐私政策》', false); return; }
    const email = f.email ? f.email.value.trim() : '';
    const type = f.type ? f.type.value : '';
    const data = {
      name, phone, company: f.company.value.trim(),
      message: message + (email ? '（邮箱：' + email + '）' : ''),
      source: '业务咨询' + (type ? ' · ' + type : ''),
      consent: true
    };
    const btn = cf.querySelector('button[type="submit"]');
    const old = btn ? btn.textContent : '';
    if (btn) { btn.disabled = true; btn.textContent = '提交中…'; }
    try {
      const r = await fetch('/api/lead', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) });
      if (!r.ok) throw new Error('bad');
      try { window.__track && window.__track('form_submit', { source: (data && data.source) || '业务咨询' }); } catch (_) {}
      setMsg('提交成功，我们会尽快与您联系！', true);
      cf.reset();
    } catch (_) {
      setMsg('提交失败，请稍后重试或拨打咨询热线', false);
    } finally {
      if (btn) { btn.disabled = false; btn.textContent = old; }
    }
  });
})();

