let heroSlides = [], heroDots = [], heroCur = 0, heroTimer = null;
const heroShow = (n) => {
  if (!heroSlides.length) return;
  heroCur = (n + heroSlides.length) % heroSlides.length;
  heroSlides.forEach((s, k) => s.classList.toggle('is-active', k === heroCur));
