      catsEl.querySelectorAll('[data-faqcat]').forEach((x) => { x.className = catCls(x.getAttribute('data-faqcat') === curCat); });
      if (selEl) selEl.value = curCat;
    };
    catsEl.innerHTML = order.map((c) => `<button type="button" data-faqcat="${esc(c)}" class="${catCls(false)}"><span class="w-1.5 h-1.5 rounded-full bg-current opacity-70 shrink-0"></span><span class="truncate">${esc(c)}</span></button>`).join('');
    if (selEl) selEl.innerHTML = `<option value="${ALL}">全部</option>` + order.map((c) => `<option value="${esc(c)}">${esc(c)}</option>`).join('');   // 下拉：全部 + 各问题类型（联动）
    render();
    catsEl.addEventListener('click', (e) => { const b = e.target.closest('[data-faqcat]'); if (!b) return; curCat = b.getAttribute('data-faqcat'); render(); });
    if (selEl) selEl.addEventListener('change', () => { curCat = selEl.value; render(); });   // 分类切换即生效（保留当前关键词）
    const doSearch = () => { q = (searchEl ? searchEl.value : '').trim(); render(); };
    const sbtn = document.getElementById('faq-search-btn'); if (sbtn) sbtn.addEventListener('click', doSearch);
    if (searchEl) searchEl.addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); doSearch(); } });
    if (localStorage.getItem('lang') !== 'en') {   // 英文版不显示「常见问题」栏目（标签+导航项）
      document.querySelectorAll('.faq-tab, .faq-nav-link').forEach((el) => { const t = el.closest('li') || el; t.style.display = ''; });
    }
  });

  // 服务支持·销售网络
  load('salesNetwork').then((items) => {
    if (!items) return;
    const pin = '<svg class="w-4 h-4 mt-0.5 shrink-0 text-primary" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M12 21s-7-5.5-7-11a7 7 0 0114 0c0 5.5-7 11-7 11z"/><circle cx="12" cy="10" r="2.5"/></svg>';
    const tel = '<svg class="w-4 h-4 shrink-0 text-primary" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M5 4h4l2 5-2.5 1.5a11 11 0 005 5L15 13l5 2v4a2 2 0 01-2 2A16 16 0 013 6a2 2 0 012-2z"/></svg>';
    const mail = '<svg class="w-4 h-4 shrink-0 text-primary" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M4 6h16v12H4z"/><path d="M4 7l8 6 8-6"/></svg>';
    set('sales-grid', items.map((s) => `<div class="fade-in-up is-visible bg-white border border-gray-200 rounded-lg p-6">
      <p class="text-base font-medium text-gray-900">${esc(s.region)}</p>
      <div class="mt-4 space-y-2.5 text-sm text-gray-600">
        ${s.address ? `<p class="flex items-start gap-2">${pin}${esc(s.address)}</p>` : ''}
        ${s.phone ? `<p class="flex items-center gap-2">${tel}${esc(s.phone)}</p>` : ''}
        ${s.email ? `<p class="flex items-center gap-2">${mail}${esc(s.email)}</p>` : ''}
      </div></div>`).join(''));
  });

  // 投资者关系·公司公告
  load('announcements').then((items) => {
    if (!items) return;
    const chev = '<svg class="chevron w-4 h-4 shrink-0 text-gray-400" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M4 6l4 4 4-4"/></svg>';
    set('announce-list', items.map((a) => {
      const att = a.attachment ? `<p class="mt-3"><a href="${esc(a.attachment)}" download class="inline-flex items-center gap-1.5 text-primary hover:text-primary-dark"><svg class="w-4 h-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M12 4v12M7 11l5 5 5-5M5 20h14"/></svg>下载附件</a></p>` : '';
      return `<details class="group border-b border-gray-200 last:border-0">
        <summary class="flex items-center justify-between gap-4 py-4 px-5 cursor-pointer hover:bg-gray-50">
          <span class="flex items-center gap-4 min-w-0"><time class="text-sm text-gray-400 shrink-0">${esc(a.date)}</time><span class="text-sm font-medium text-gray-900 truncate">${esc(a.title)}</span></span>
          ${chev}
        </summary>
        <div class="px-5 pb-5 text-sm text-gray-600 leading-relaxed">${a.body || ''}${att}</div>
      </details>`;
    }).join(''));
  });

  // 新闻资讯 + 行业洞察（同页，「行业洞察」为独立标签；有已发布洞察时才出现该标签）
  Promise.all([load('news'), load('insights')]).then(([newsItems, insightItems]) => {
    const items = newsItems || [];
    const insights = (insightItems || []).map((n) => Object.assign({}, n, { category: '行业洞察', _insight: true }));
    // 顶部/移动/页脚菜单中的「行业洞察」：有已发布洞察才显示，全部下架则隐藏
    document.querySelectorAll('.insight-nav-link').forEach((el) => { const t = el.closest('li') || el; t.style.display = insights.length ? '' : 'none'; });
    if (!items.length && !insights.length) return;
    const all = items.concat(insights);
    const tag = (c) => c === '行业洞察' ? 'bg-primary text-white' : ((c === '市场活动') ? 'bg-primary-light text-primary' : 'bg-gray-100 text-primary-dark');
    const PAGE = 12;
    let curCat = '全部', shown = 0;
    const listFor = () => curCat === '全部' ? items : (curCat === '行业洞察' ? insights : items.filter((n) => n.category === curCat));
    const imgRe = /<img[^>]+src=["']([^"']+)["']/i;
    const thumbOf = (n) => { const m = (n.body || '').match(imgRe); return m ? m[1] : (n.cover || 'images/news-expo.jpg'); };
    const card = (n) => `<button type="button" data-news="${esc(n.id)}" class="w-full text-left flex items-center gap-4 md:gap-5 py-4 md:py-5 group">
          <span class="shrink-0 w-28 h-20 md:w-36 md:h-24 overflow-hidden rounded-md bg-gray-100">
            <img src="${esc(thumbOf(n))}" alt="${esc(n.title)}" loading="lazy" onerror="this.onerror=null;this.src='${esc(n.cover || 'images/news-expo.jpg')}'" class="w-full h-full object-cover group-hover:scale-[1.03] transition-transform duration-300">
          </span>
          <span class="flex-1 min-w-0">
            <span class="flex items-center gap-2 mb-1.5">
              <span class="inline-flex items-center px-2 py-0.5 rounded-sm text-xs ${tag(n.category)}">${esc(n.category)}</span>
              <time class="text-xs md:text-sm text-gray-400 tabular-nums">${esc(n.date)}</time>
            </span>
            <span class="block text-sm md:text-base font-medium text-gray-800 group-hover:text-primary transition-colors line-clamp-2">${esc(n.title)}</span>
          </span>
        </button>`;
    const cats = ['全部'].concat(Array.from(new Set(items.map((n) => n.category)))).concat(insights.length ? ['行业洞察'] : []);
    const countOf = (c) => c === '行业洞察' ? insights.length : items.filter((n) => n.category === c).length;
    const renderTabs = () => set('news-tabs', cats.map((c) => `<button type="button" data-cat="${esc(c)}" class="inline-flex items-center px-4 py-1.5 rounded text-sm border transition-colors ${c === curCat ? 'border-primary bg-primary-light text-primary' : 'border-gray-200 text-gray-600 hover:border-primary hover:text-primary'}">${esc(c)}${c === '全部' ? '' : ' <span class="ml-1 text-xs opacity-70">' + countOf(c) + '</span>'}</button>`).join(''));
    const renderGrid = (reset) => {
      const list = listFor();
      shown = reset ? PAGE : shown + PAGE;
      shown = Math.min(shown, list.length);
      set('news-grid', list.slice(0, shown).map(card).join(''));
      const empty = document.getElementById('news-empty'); if (empty) empty.classList.toggle('hidden', list.length > 0);
      const more = document.getElementById('news-more'); if (more) more.style.display = shown < list.length ? '' : 'none';
    };
    renderTabs();
    renderGrid(true);
    const tabsEl = document.getElementById('news-tabs');
    if (tabsEl) tabsEl.addEventListener('click', (e) => { const b = e.target.closest('[data-cat]'); if (!b) return; curCat = b.getAttribute('data-cat'); renderTabs(); renderGrid(true); });
    const moreEl = document.getElementById('news-more');
    if (moreEl) moreEl.addEventListener('click', () => renderGrid(false));
    // 新闻详情弹窗
    const nm = document.getElementById('news-modal');
    const closeNews = () => { nm.classList.add('hidden'); nm.classList.remove('flex'); document.body.classList.remove('overflow-hidden'); };
    const openNews = (n) => {
      document.getElementById('news-modal-cat').textContent = n.category || '';
      document.getElementById('news-modal-date').textContent = (n.date || '') + (n.author ? ' · ' + n.author : '');
      document.getElementById('news-modal-title').textContent = n.title || '';
      document.getElementById('news-modal-body').innerHTML = n.body || ('<p>' + esc(n.summary || '') + '</p>');
      nm.classList.remove('hidden'); document.body.classList.add('overflow-hidden'); nm.scrollTop = 0;
    };
    window.openNewsById = (id) => { const n = all.find((x) => x.id === id); if (n) openNews(n); };
    window.newsSelectCat = (c) => { if (!cats.includes(c)) return; curCat = c; renderTabs(); renderGrid(true); };
    const grid = document.getElementById('news-grid');
    if (grid) grid.addEventListener('click', (e) => { const b = e.target.closest('[data-news]'); if (!b) return; const n = all.find((x) => x.id === b.getAttribute('data-news')); if (n) openNews(n); });
    document.getElementById('news-modal-close').addEventListener('click', closeNews);
    document.addEventListener('keydown', (e) => { if (e.key === 'Escape' && !nm.classList.contains('hidden')) closeNews(); });
  });
})();

