  const swapAttrs = (el) => {
    ['placeholder', 'aria-label', 'alt', 'title'].forEach((a) => {
      if (el.hasAttribute && el.hasAttribute(a)) { const v = (el.getAttribute(a) || '').trim(); if (DICT[v]) el.setAttribute(a, DICT[v]); }
    });
  };
  const swapTextNode = (n) => { const t = n.nodeValue.trim(); if (t && DICT[t]) n.nodeValue = n.nodeValue.replace(t, DICT[t]); };
  const run = (root) => {
    try {
      if (root.nodeType === 3) { swapTextNode(root); return; }
      if (root.nodeType !== 1) return;
      const w = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
      const ns = []; while (w.nextNode()) ns.push(w.currentNode);
      ns.forEach(swapTextNode);
      swapAttrs(root); root.querySelectorAll('*').forEach(swapAttrs);
    } catch (e) {}
  };

  run(document.body);
  // 语言按钮文案改为「中文」（便于切回）
  document.querySelectorAll('.lang-label').forEach((el) => { el.textContent = '中文'; });
  // 英文版隐藏标记为 data-zh-only 的元素（如新闻）
  document.querySelectorAll('[data-zh-only]').forEach((el) => { el.style.display = 'none'; });
  // 监听动态渲染内容（产品/方案/招聘等），插入后即翻译其中静态标签
  new MutationObserver((muts) => muts.forEach((m) => m.addedNodes.forEach((node) => run(node))))
    .observe(document.body, { childList: true, subtree: true });
})();

(function () {
  var EP = '/api/track';
  function uid() { try { return crypto.randomUUID(); } catch (e) { return Date.now().toString(36) + Math.random().toString(16).slice(2); } }
  function get(store, key) { try { var v = store.getItem(key); if (!v) { v = uid(); store.setItem(key, v); } return v; } catch (e) { return uid(); } }
  var vid = get(localStorage, '_lk_vid');
  var sid = get(sessionStorage, '_lk_sid');
  function lang() { try { return localStorage.getItem('lang') || document.documentElement.lang || 'zh'; } catch (e) { return 'zh'; } }
  function consented() { try { return localStorage.getItem('_lk_consent') === 'yes'; } catch (e) { return false; } }
  function send(data) {
    if (!consented()) return;   // 未同意不采集（隐私门控）
    data.vid = vid; data.sid = sid; data.lang = lang(); data.ref = document.referrer || ''; data.q = location.search || '';
    try { if (navigator.sendBeacon) { navigator.sendBeacon(EP, new Blob([JSON.stringify(data)], { type: 'application/json' })); return; } } catch (e) {}
    try { fetch(EP, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data), keepalive: true }); } catch (e) {}
  }
  var lastPath = '', enterTs = 0;
  function flushDuration() { if (lastPath && enterTs) { send({ type: 'event', name: '_duration', path: lastPath, dur: Math.round((Date.now() - enterTs) / 1000) }); } }
  function pageview() {
    var path = location.pathname + location.hash;
    if (path === lastPath) return;
    flushDuration();
    lastPath = path; enterTs = Date.now();
    send({ type: 'pageview', path: path, title: document.title });
  }
  window.addEventListener('hashchange', pageview);
  window.addEventListener('load', pageview);
  document.addEventListener('visibilitychange', function () { if (document.visibilityState === 'hidden') flushDuration(); });
  window.addEventListener('pagehide', flushDuration);
  // 转化/自定义事件统一入口：window.__track('form_submit', { source: '...' })
  window.__track = function (name, extra) { send({ type: 'event', name: name, path: location.pathname + location.hash, extra: extra || {} }); };
  // 电话/邮箱点击 + 视频播放（全局委托）
  document.addEventListener('click', function (e) {
    var a = e.target.closest && e.target.closest('a[href^="tel:"], a[href^="mailto:"]');
    if (a) { var h = a.getAttribute('href') || ''; window.__track(h.indexOf('tel:') === 0 ? 'tel_click' : 'mail_click', { to: h.replace(/^(tel:|mailto:)/, '') }); }
  });
  document.addEventListener('play', function (e) { if (e.target && e.target.tagName === 'VIDEO') { window.__track('video_play', { src: (e.target.currentSrc || e.target.src || '').split('/').pop() }); } }, true);
  // 隐私同意条：首访显示；同意后才开始采集
  function consentBar() {
    var bar = document.getElementById('lk-consent'); if (!bar) return;
    var c = null; try { c = localStorage.getItem('_lk_consent'); } catch (e) {}
    if (!c) bar.classList.remove('hidden');
    var choose = function (v) { try { localStorage.setItem('_lk_consent', v); } catch (e) {} bar.classList.add('hidden'); if (v === 'yes') pageview(); };
    var y = document.getElementById('lk-consent-yes'), n = document.getElementById('lk-consent-no');
    if (y) y.addEventListener('click', function () { choose('yes'); });
    if (n) n.addEventListener('click', function () { choose('no'); });
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', consentBar); else consentBar();
  if (document.readyState !== 'loading') pageview();
})();
